          const here = s.eType[k] === type && Math.abs(s.ex[k] - (col + 0.5) * S.CELL) < 0.01 ? 1 : 0;
          if (here && !was[r * M.ENEMY_SLOTS + k]) { spawns[r]++; if (seenAt[r] < 0) seenAt[r] = step; if (!view) early = true; }
