    for (let k = 0; k < 2; k++) { sim.setInput(M.IN.JUMP); watch(); sim.setInput(0); for (let i = 0; i < 120; i++) watch(); }
    const side = M.create({ seed: 7, stage: testStage });
    side.setInput(M.IN.RIGHT); side.simulate(4);
