          const sim = fresh(), t = sim.state, r = slotOf(t, E.RAM), start = lo - 0.25;
          for (let i = 0; i < 1200 && Math.abs(t.px[0] - start) > 0.02; i++) step(sim, toward(t, start));
          t.pInvincible[0] = 0;
          let was = t.eRoutine[r], go = false, dead = false, i = 0;
