    play(held, 40000, 40000 + G.CONFIG.PAUSE_MAX_MS - 1000, { here: 0 });
    const still = held.state.paused && held.state.now === heldAt && held.state.state === heldState && JSON.stringify(held.ghosts.map((g) => [g.on, g.x, g.z])) === stood;
    let heldOutcome = 0;
