      for (let i = 0; i < parts.length; i++) { const q = turn(parts[i]), d = Math.abs(q[0] * start[i][0] + q[1] * start[i][1] + q[2] * start[i][2] + q[3] * start[i][3]);
        high[i] = Math.max(high[i], 2 * Math.acos(Math.min(1, d))); }
      compact &&= gorilla.sitCompact;
