    const gate=BL.oogaPortal.create({radius:2.5,outerRadius:2.8,aperture:P,position:{x:0,y:P.height/2,z:0},rotation:{x:Math.PI/2,y:0,z:0},now:()=>time,destinations:[{id:"bifrost",enabled:true}],onTraverse:()=>crossings++});
