    const longestGap = list => { let best = 0; for (let k = 0; k < list.length; k++) { const a = list[k], b = list[(k + 1) % list.length], gap = (b - a - 1 + N) % N; best = Math.max(best, list.length === 1 ? N - 1 : gap); } return best; };
