// Rescue dogs have two shadow variants of body/legs/tail for each breed, plus poop and flies, all built once.
// Their camera-dependent visibility (and a brief muzzle flash/banana projectile) may first upload after the
// warm itinerary. Prepare only those exact existing meshes, without changing any scene state or resource bound.
const warmDsbRoomResidents = async b => {
  const r = await b.evaluate(`(() => {
    const B = __ooga, nodes = window.__dsbRescueBatches || [], before = nodes.map(n => [n.geometry, n.visible, n.instanceCount, n.instanceData]);
    const geometries = new Set(nodes.map(n => n.geometry));
    geometries.add(B.dsb.avatar.parts.gunFlash.geometry); geometries.add(B.dsb.avatar.parts.snack.geometry);
    let prepared = true;
    for (const geometry of geometries) prepared = B.renderer.prepareGeometry(geometry) && prepared;
    const resident = new Set(B.renderer.geometryRecords()), records = B.renderer.stats.records;
    for (const geometry of geometries) prepared = B.renderer.prepareGeometry(geometry) && prepared;
    return { batches: nodes.length, expected: BL.rescueDogs.BREEDS.length * 6 + 2, geometries: geometries.size,
      prepared: prepared && [...geometries].every(g => resident.has(g)), idempotent: B.renderer.stats.records === records,
      unchanged: nodes.every((n, i) => n.geometry === before[i][0] && n.visible === before[i][1] && n.instanceCount === before[i][2] && n.instanceData === before[i][3]) };
  })()`);
  record("DSB room residency: the finite rescue batches, muzzle flash and banana warm once without changing visibility, counts or instance storage",
    r.batches === r.expected && r.geometries === r.expected + 2 && r.prepared && r.idempotent && r.unchanged, JSON.stringify(r));
};
const dsbDoorHandoff = { name: "dsb door handoff", why: "regression: building fades reset pitch, zoom and held movement", run: async b => {
  await b.evaluate(doorCameraTrace);
  const rows = await b.evaluate(`(() => {
    const B = __ooga, P = B.pilot, I = B.dsb.interiors, d = I.registry.get("meme-factory"), rows = [];
    const step = () => { BL.scenes.dsb.update(1 / 60, 0); __doorCameraTrace.sample(B.camera, I.fade, I.active?.id || "exterior"); };
    const key = (down) => window.dispatchEvent(new KeyboardEvent(down ? "keydown" : "keyup", { key: "s", code: "KeyS", bubbles: true }));
    for (const view of ["orbit", "first-person"]) for (const release of [false, true]) {
      if (P.aiming) P.modeAction("mode-toggle");
      if (view === "first-person") P.enterClose(); else P.exitClose();
      for (const inside of [true, false]) {
        const point = inside ? d.entry : I.active.room.exit;
        P.navigate({ position: point, yaw: inside ? d.building.yaw : Math.PI, pitch: 0.22, dist: 7 });
        for (let i = 0; i < 30; i++) step();
        const saved = P.viewState();
        __doorCameraTrace.reset();
        const accepted = I.request(point);
        key(true); P.controls.reset(); if (release) key(false);
        for (let i = 0; i < 30 && I.transitioning; i++) step();
        const got = P.viewState(), axes = { ...P.controls.read() };
        const cameraInside = () => {
          if (!I.active) return true;
          const p = B.camera.position, b = I.active.room.bounds;
          return p.x >= b.minX + .2 - 1e-6 && p.x <= b.maxX - .2 + 1e-6
            && p.z >= b.minZ + .2 - 1e-6 && p.z <= b.maxZ - .2 + 1e-6
            && p.y >= I.active.room.groundAt(p.x, p.z) + .74 - 1e-6 && p.y <= I.active.room.ceiling - .7 + 1e-6;
        };
        let contained = cameraInside();
        for (let i = 0; i < 30; i++) { step(); contained = cameraInside() && contained; }
        key(false);
        rows.push({ contained, camera: __doorCameraTrace.result(), view, release, inside, accepted, active: !!I.active, saved, got, y: axes.y });
      }
    }
    return rows;
  })()`);
  record("DSB doors: camera settles behind the black fade with no visible arrival sweep",
    rows.every(r => r.camera.frames > 30 && r.camera.yaw < 0.12 && r.camera.pitch < 0.12 && r.camera.eye < 0.75), JSON.stringify(rows.map(r => ({ view: r.view, inside: r.inside, ...r.camera }))));
  record("DSB doors: restored first-person and orbit eyes stay inside the room after handoff, at rest and walking",
    rows.every(r => r.contained), JSON.stringify(rows));
  record("DSB doors: entry and exit preserve first-person/orbit pitch and zoom, resume held S, and do not revive released keys",
    rows.every(r => r.accepted && r.active === r.inside && r.got.view === r.saved.view && Math.abs(r.got.pitch - r.saved.pitch) < 0.01
      && Math.abs(r.got.distance - r.saved.distance) < 0.01 && r.y === (r.release ? 0 : -1)), JSON.stringify(rows));
} };
const dsbInteriorCheckpoint = { name: "dsb interior checkpoint", why: "rule: a real door isolates its room and returns the same player to current exterior weather without accumulating resources", run: async b => {
  const step=()=>b.evaluate('for(let i=0;i<36;i++)BL.scenes.dsb.update(1/60,i/60)');
  const tap=async()=>{
    const p=await b.evaluate('(()=>{const e=document.getElementById("dsb-context"),r=e.getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,visible:!e.hidden};})()');
    if(!p.visible)throw new Error("Expected a reachable interior door");
    // Like browser.click, enqueue release on time instead of turning a tap into
    // a multi-second hold while a slow Canvas frame delays the start acknowledgement.
    const pressed=b.send("Input.dispatchTouchEvent",{type:"touchStart",touchPoints:[{x:p.x,y:p.y}],timestamp:Date.now()/1000});
    await b.sleep(40);
    const released=b.send("Input.dispatchTouchEvent",{type:"touchEnd",touchPoints:[],timestamp:Date.now()/1000});
    await Promise.all([pressed,released]);await step();
  };
  await b.key(" ");await step();
  const entry=await b.evaluate(`(()=>{const B=__ooga,D=B.dsb,I=D.interiors,S=D.weather.shared.state;window.__interiorCheck={avatar:D.avatar,land:D.land,nature:D.nature,water:D.water,indoor:I.lighting,read:B.daylight.read};
    return {active:!!I.active,exterior:D.exterior.visible,drops:S.drops,master:S.masterLevel,feet:D.avatar.root.position.y-D.avatar.baseY,camera:{...B.camera.position},audio:I.audio.stats,label:document.querySelector("#dsb-context").textContent};})()`);
  record("DSB interior: Space at the exterior door enters, gates weather and starts one workshop graph",entry.active&&!entry.exterior&&entry.drops===0&&entry.master===0&&Math.abs(entry.feet-0)<.001&&Math.abs(entry.camera.x)<2&&entry.audio.connected&&entry.audio.sources===3,JSON.stringify(entry));
  // Actual held movement, then a supported doorway return through the same controller.
  const before=await b.evaluate('({...__ooga.dsb.avatar.root.position})');
  await b.send("Input.dispatchKeyEvent",{type:"keyDown",key:"d",code:"KeyD"});await step();
  await b.send("Input.dispatchKeyEvent",{type:"keyUp",key:"d",code:"KeyD"});
  const moved=await b.evaluate(`(()=>{const D=__ooga.dsb,I=D.interiors,p=D.avatar.root.position;return {p:{...p},floor:I.groundAt(p.x,p.z),wall:I.walkable(0,18,0,23,0,2,D.avatar),counter:I.walkable(0,-1,0,-7,0,2,D.avatar),table:I.walkable(0,7,0,3,0,2,D.avatar)};})()`);
  record("DSB interior: held movement works on the floor and swept collision blocks walls, tables and counter",Math.hypot(moved.p.x-before.x,moved.p.z-before.z)>.2&&moved.floor===0&&!moved.wall&&!moved.counter&&!moved.table,JSON.stringify(moved));
  await b.evaluate('(()=>{const B=__ooga,I=B.dsb.interiors;B.pilot.navigate({position:I.active.room.spawn,yaw:Math.PI,pitch:.22,dist:3});B.dsb.weather.setMode("rain");B.daylight.read=()=>0;for(let i=0;i<480;i++)BL.scenes.dsb.update(1/60,i/60);})()');
  const isolation=await b.evaluate('({same:BL.scenes.dsb.renderOpts===__interiorCheck.indoor,exterior:__ooga.dsb.weather.state.exterior,drops:__ooga.dsb.weather.shared.state.drops,night:__ooga.renderOpts.day})');
  await tap();
  const exit=await b.evaluate(`(()=>{const B=__ooga,D=B.dsb,I=D.interiors,p=D.avatar.root.position,e=I.registry.get("meme-factory").entry;return {active:!!I.active,same:D.avatar===__interiorCheck.avatar&&D.land===__interiorCheck.land&&D.water===__interiorCheck.water&&D.nature===__interiorCheck.nature,distance:Math.hypot(p.x-e.x,p.z-e.z),floor:p.y-D.avatar.baseY-D.groundAt(p.x,p.z,p.y-D.avatar.baseY),cameraClear:D.land.clearAt(B.camera.position.x,B.camera.position.z,.1),weather:D.weather.state.mode,night:B.renderOpts.day,lamps:B.renderOpts.lampFactor,drops:D.weather.shared.state.drops,master:D.weather.shared.state.masterLevel,audio:I.audio.stats};})()`);
  record("DSB interior: touch exit restores the same player/building and current night rain, not entry weather",isolation.same&&!isolation.exterior&&isolation.drops===0&&isolation.night===0&&!exit.active&&exit.same&&exit.distance<.01&&exit.cameraClear&&Math.abs(exit.floor)<.01&&exit.weather==="rain"&&exit.night===0&&exit.lamps>.9&&exit.drops>0&&exit.master>0&&!exit.audio.connected,JSON.stringify({isolation,exit}));
  await b.evaluate('__ooga.daylight.read=__interiorCheck.read');
  if(!await untilPage(b,'B.scene==="dsb"&&!B.transitioning&&!B.dsb.interiors.active&&(B.renderer.kind==="canvas2d"||B.renderer.ready)'))throw Error("DSB exterior did not draw after restoring daylight");
  const snapshot=()=>b.evaluate(`(()=>{const B=__ooga,I=B.dsb.interiors;let nodes=0;const geometries=new Set();const visit=n=>{nodes++;if(n.geometry)geometries.add(n.geometry);for(const c of n.children)visit(c);};visit(BL.scenes.dsb.root);return {counts:{nodes,geometries:geometries.size,rooms:I.rooms.size,targets:BL.scenes.dsb.input.targetCount,audio:I.audio.stats.sources,contexts:I.audio.stats.contexts,radioSources:B.dsb.noderunner.audio?.stats.sources,radioStarts:B.dsb.noderunner.audio?.stats.starts,records:B.renderer.stats.records,room:I.active?.room.id||null,lights:B.renderOpts.lightCount,textures:B.renderer.stats.waterTextures||0,remotes:BL.scenes.dsb.stats().remotePlayers},geometry:${gpuGeometryPageSnapshot}};})()`);
  const listenerCount=async()=>{
    const obj=await b.send("Runtime.evaluate",{expression:"document"});
    const result=await b.send("DOMDebugger.getEventListeners",{objectId:obj.result.result.objectId});
    await b.send("Runtime.releaseObject",{objectId:obj.result.result.objectId});return result.result.listeners.length;
  };
  await warmDsbRoomResidents(b);
  const initial=await snapshot(),base=initial.counts,listeners=await listenerCount();
  let cycles=1;
  for(;cycles<10;cycles++){await tap();await b.evaluate('__ooga.pilot.navigate({position:__ooga.dsb.interiors.active.room.spawn,yaw:Math.PI,pitch:.22,dist:3})');await step();await tap();}
  if(!await untilPage(b,'B.scene==="dsb"&&!B.transitioning&&!B.dsb.interiors.active&&(B.renderer.kind==="canvas2d"||B.renderer.ready)'))throw Error("DSB exterior did not draw after ten door cycles");
  const final=await snapshot(),end=final.counts,listenersEnd=await listenerCount();
  const bounded=Object.keys(base).every(key=>key==="records"?end[key]<=base[key]:end[key]===base[key])&&listeners===listenersEnd;
  record("DSB interior: ten complete door cycles retain bounded nodes, geometry, handlers and audio sources",bounded,JSON.stringify({cycles,base,end,listeners,listenersEnd,...(bounded?{}:{geometry:gpuGeometryDelta(initial.geometry,final.geometry)})}));
  await b.evaluate('window.__interiorCheck.old=__ooga.dsb.interiors;__ooga.go("dsb",null,true);__ooga.advance(.05)');
  const clean=await b.evaluate('({rooms:__interiorCheck.old.rooms.size,audio:__interiorCheck.old.audio.stats.contexts,fresh:__ooga.dsb.interiors.rooms.size,visible:__ooga.dsb.exterior.visible})');
  record("DSB interior: scene departure releases the room and its AudioContext",clean.rooms===0&&clean.audio===0&&clean.fresh===0&&clean.visible,JSON.stringify(clean));
  await b.evaluate('delete window.__interiorCheck');
  record("DSB interior: runtime console remains clean",b.logs.length===0,b.logs.join(" | "));
}};
scene("dsb",{label:"door handoff",query:"&view=meme-factory",opts:{motion:true},steps:[dsbDoorHandoff]});
scene("dsb",{label:"interior checkpoint",query:"&view=meme-factory&weather=storm&time=1200",steps:[dsbInteriorCheckpoint]});
